import{_ as n,c as a,o as r,ag as t}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"Datenschutzerklärung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/privacy.md","filePath":"de/guide/privacy.md","lastUpdated":1794112334000}'),i={name:"de/guide/privacy.md"};function s(l,e,o,u,h,d){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="datenschutzerklarung" tabindex="-1">Datenschutzerklärung <a class="header-anchor" href="#datenschutzerklarung" aria-label="Permalink to &quot;Datenschutzerklärung&quot;">​</a></h1><h2 id="datenerfassung" tabindex="-1">Datenerfassung <a class="header-anchor" href="#datenerfassung" aria-label="Permalink to &quot;Datenerfassung&quot;">​</a></h2><p>Der Entwickler erfasst über diese App keinerlei Daten.</p><h3 id="informationen-die-wir-nicht-erfassen" tabindex="-1">Informationen, die wir nicht erfassen <a class="header-anchor" href="#informationen-die-wir-nicht-erfassen" aria-label="Permalink to &quot;Informationen, die wir nicht erfassen&quot;">​</a></h3><ul><li>Personenbezogene Daten</li><li>Nutzungsstatistiken</li><li>Geräteinformationen</li><li>Standortdaten</li><li>Bildinhalte oder Metadaten</li><li>Browserverlauf</li><li>Sonstige Nutzerdaten</li></ul><h3 id="chrome-erweiterung" tabindex="-1">Chrome-Erweiterung <a class="header-anchor" href="#chrome-erweiterung" aria-label="Permalink to &quot;Chrome-Erweiterung&quot;">​</a></h3><p>Die Nicasa Chrome-Erweiterung fordert Zugriff auf Seiteninhalte ausschließlich zum Extrahieren von Bild-URLs für die Bildanzeige an. Die Erweiterung:</p><ul><li>liest oder speichert den Browserverlauf nicht</li><li>verfolgt kein Nutzerverhalten</li><li>überträgt keine Daten an externe Server</li><li>verarbeitet Bild-URLs ausschließlich lokal in deinem Browser</li></ul><h3 id="lokale-verarbeitung" tabindex="-1">Lokale Verarbeitung <a class="header-anchor" href="#lokale-verarbeitung" aria-label="Permalink to &quot;Lokale Verarbeitung&quot;">​</a></h3><p>Die gesamte Bildverarbeitung, -bearbeitung und -anzeige erfolgt lokal auf deinem Gerät. Es werden keine Bilder oder Daten auf externe Server hochgeladen.</p><h3 id="berechtigungen" tabindex="-1">Berechtigungen <a class="header-anchor" href="#berechtigungen" aria-label="Permalink to &quot;Berechtigungen&quot;">​</a></h3><p>Nicasa fordert unter macOS die folgenden Berechtigungen an:</p><ul><li><strong>Bildschirmaufnahme</strong>: erforderlich für die Screenshot-Funktion</li><li><strong>Bedienungshilfen</strong>: optional, für Funktionen des Overlay-Modus</li><li><strong>Dateien und Ordner</strong>: Zugriff auf vom Nutzer ausgewählte Verzeichnisse zur Bildanzeige</li></ul><p>Diese Berechtigungen lassen sich unter Systemeinstellungen &gt; Datenschutz &amp; Sicherheit verwalten.</p><h3 id="dienste-von-drittanbietern" tabindex="-1">Dienste von Drittanbietern <a class="header-anchor" href="#dienste-von-drittanbietern" aria-label="Permalink to &quot;Dienste von Drittanbietern&quot;">​</a></h3><p>Nicasa bindet keine Analyse-, Werbe- oder Datenerfassungsdienste von Drittanbietern ein.</p><h3 id="datenschutz-optionen" tabindex="-1">Datenschutz-Optionen <a class="header-anchor" href="#datenschutz-optionen" aria-label="Permalink to &quot;Datenschutz-Optionen&quot;">​</a></h3><p>Wenn du Datenschutzrechte ausüben möchtest (zum Beispiel Anfragen zu Auskunft, Löschung, Datenübertragbarkeit oder Widerspruch) oder glaubst, dass Nicasa personenbezogene Daten über dich hat, kannst du eine Anfrage über einen der folgenden Wege stellen:</p><ul><li>E-Mail: <a href="mailto:nicasa@w3cub.com" target="_blank" rel="noreferrer">nicasa@w3cub.com</a></li><li>Datenschutz-Issue eröffnen: <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li><li>Unsere Seite „Datenschutz-Optionen“ verwenden: /de/guide/privacy-choices</li></ul><p>Da Nicasa, wie oben beschrieben, keine personenbezogenen Daten erfasst, werden viele Anfragen mit der Bestätigung beantwortet, dass keine personenbezogenen Daten vorliegen. Sollten wir in künftigen Versionen personenbezogene Daten erfassen, bieten diese Seite und das Formular für Datenschutz-Optionen eine Möglichkeit, Anfragen zu stellen und zu verfolgen.</p><p>Wir bemühen uns, berechtigte Datenschutzanfragen innerhalb von 30 Tagen zu beantworten.</p><h3 id="aktualisierungen" tabindex="-1">Aktualisierungen <a class="header-anchor" href="#aktualisierungen" aria-label="Permalink to &quot;Aktualisierungen&quot;">​</a></h3><p>Diese Datenschutzerklärung kann mit neuen Versionen der App aktualisiert werden. Über wesentliche Änderungen werden Nutzer informiert.</p><h3 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h3><p>Bei Fragen zum Datenschutz kontaktiere uns über das <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub-Repository</a>.</p>',25)])])}const f=n(i,[["render",s]]);export{g as __pageData,f as default};
